  // --- Dedicated Credit Ledger Handlers ---
  const [showCreditLedgerModal, setShowCreditLedgerModal] = useState(false);
  const [creditLedgerSearch, setCreditLedgerSearch] = useState("");
  const [activePayCreditPatient, setActivePayCreditPatient] = useState<any | null>(null);
  const [payCreditAmount, setPayCreditAmount] = useState("");
  const [payCreditRefundDate, setPayCreditRefundDate] = useState("");

  const groupedCredits = useMemo(() => {
    const matched: { [phoneOrName: string]: any } = {};

    const filtered = allCreditRecords.filter(r => {
      const bal = Number(r.balance) || 0;
      if (bal <= 0) return false;

      if (!creditLedgerSearch) return true;
      const q = creditLedgerSearch.toLowerCase();

      const nameMatch = (r.patientName || "").toLowerCase().includes(q);
      const phoneMatch = (r.patientPhone || "").toLowerCase().includes(q);
      const addressMatch = (r.patientAddress || r.patientArea || "").toLowerCase().includes(q);
      const recDate = r.date || "";
      const dateMatch = recDate.toLowerCase().includes(q);

      return nameMatch || phoneMatch || addressMatch || dateMatch;
    });

    filtered.forEach(r => {
      const key = r.patientPhone || r.patientName || "Unknown";
      if (!matched[key]) {
        matched[key] = {
          patientName: r.patientName,
          patientPhone: r.patientPhone || "N/A",
          patientAddress: r.patientAddress || r.patientArea || "N/A",
          totalCredit: 0,
          history: [],
          latestDate: r.date || "",
        };
      }
      matched[key].totalCredit += Number(r.balance) || 0;
      matched[key].history.push(r);
    });

    return Object.values(matched);
  }, [allCreditRecords, creditLedgerSearch]);

  const handleCreditRecallWhatsApp = (debtor: any) => {
    const clinicName = user.name || "आमचे क्लिनिक";
    const patientName = debtor.patientName;
    const totalCredit = debtor.totalCredit;

    // Marathi template
    const msg = `🏥 *${clinicName}* 🏥\n\nप्रिय *${patientName}*,\n\nआपल्या उपचारांचे एकूण प्रलंबित बिल *₹${totalCredit}* अजून येणे बाकी आहे.\n\nकृपया आपल्या सोयीनुसार लवकरात लवकर वरील प्रलंबित रक्कमेचा भरणा करावा ही विनंती.\n\nधन्यवाद!\n*${clinicName}*`;

    openWhatsAppPreview(debtor.patientPhone, msg, "Credit Payment Recall", debtor.patientName, "credit_recall");
  };

  const handleProcessPayCredit = async () => {
    if (!activePayCreditPatient) return;
    const payAmount = Number(payCreditAmount) || 0;
    if (payAmount <= 0) return;

    try {
      const pendingRecords = [...activePayCreditPatient.history].sort((a: any, b: any) => {
        const dateA = a.createdAt?.seconds || (a.createdAt instanceof Date ? a.createdAt.getTime() : 0);
        const dateB = b.createdAt?.seconds || (b.createdAt instanceof Date ? b.createdAt.getTime() : 0);
        return dateA - dateB;
      });

      let remainingToDeduct = payAmount;

      for (const rec of pendingRecords) {
        if (remainingToDeduct <= 0) break;

        const currentBal = Number(rec.balance) || 0;
        let newBal = 0;
        let extraPaid = 0;

        if (remainingToDeduct >= currentBal) {
          newBal = 0;
          extraPaid = currentBal;
          remainingToDeduct -= currentBal;
        } else {
          newBal = currentBal - remainingToDeduct;
          extraPaid = remainingToDeduct;
          remainingToDeduct = 0;
        }

        const updatedPaidAmount = (Number(rec.paidAmount) || 0) + extraPaid;
        const updatedStatus = newBal === 0 ? "paid" : "pending";

        await firebaseService.updateDocument("credit_records", rec.id, {
          balance: newBal,
          paidAmount: updatedPaidAmount,
          status: updatedStatus,
          lastPaidAt: new Date(payCreditRefundDate),
        });
      }

      await firebaseService.addDocument("patient_payment_history", {
        clinicId: String(user.id),
        patientName: activePayCreditPatient.patientName,
        patientPhone: activePayCreditPatient.patientPhone,
        paidAmount: payAmount,
        paymentMode: "cash",
        note: `Outstanding Credit Payoff on ${payCreditRefundDate}`,
        type: "OPD Credit Pay",
        createdAt: new Date(),
      });

      if (fetchOnDemandDataRef.current) {
        await fetchOnDemandDataRef.current();
      }

      setConfirmModal({
        isOpen: true,
        title: "Payment Logged Successfully",
        message: `Received ₹${payAmount}. Remaining Credit Outstanding for ${activePayCreditPatient.patientName} is ₹${activePayCreditPatient.totalCredit - payAmount}`,
        type: "info",
        onConfirm: () => {
          setActivePayCreditPatient(null);
          setPayCreditAmount("");
          setPayCreditRefundDate("");
        }
      });

    } catch (err) {
      console.error("Error processing pay credit:", err);
    }
  };

