  const patientTimeline = useMemo(() => {
    if (!selectedPatientForPrescription || !prescriptionHistory) return [];
    return prescriptionHistory.filter((p: any) => {
      const pId = String(p.patientId || p.id || "").toLowerCase();
      const selId = String(selectedPatientForPrescription.patientId || selectedPatientForPrescription.id || "").toLowerCase();
      const pPhone = String(p.patientPhone || "").replace(/[^0-9]/g, "");
      const selPhone = String(selectedPatientForPrescription.patientPhone || "").replace(/[^0-9]/g, "");
      const pName = String(p.patientName || "").toLowerCase().trim();
      const selName = String(selectedPatientForPrescription.patientName || "").toLowerCase().trim();

      return (
        (selId && pId === selId) ||
        (selPhone && pPhone && pPhone === selPhone) ||
        (selName && pName && pName === selName)
      );
    });
  }, [prescriptionHistory, selectedPatientForPrescription]);
  const [prescriptionFetchStatus, setPrescriptionFetchStatus] = useState<"idle" | "loading" | "success" | "error">("idle");
