  const handleOPDSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isOpdSubmitting) return;
    setIsOpdSubmitting(true);
    try {
      const nextToken = isTokenSystemEnabled
        ? opdQueue.length > 0
          ? Math.max(...opdQueue.map((p) => Number(p.token) || 0)) + 1
          : 1
        : 0;
      const today = getISTDateString();

      // Calculate visit count for this patient
      const patientHistory = allOpdRecords.filter(
        (p) => p.patientPhone === opdForm.patientPhone,
      );
      const visitCount = patientHistory.length + 1;

      const cleanAmount = (amount: any) => {
        if (typeof amount === "string") {
          const cleaned = amount.replace(/[^\d.]/g, "");
          return parseFloat(cleaned) || 0;
        }
        return parseFloat(amount) || 0;
      };

      const cash = cleanAmount(opdForm.cashAmount);
      const phonepe = cleanAmount(opdForm.phonePeAmount);
      const credit = cleanAmount(opdForm.creditAmount);
      const total = cash + phonepe + credit;

      let finalToken = nextToken;
      if (opdIdToUpdate) {
        const existingTokenPatient = opdQueue.find(p => p.id === opdIdToUpdate);
        if (existingTokenPatient && existingTokenPatient.token) {
          finalToken = Number(existingTokenPatient.token) || nextToken;
        }
      }

      const opdData = {
        ...opdForm,
        cashAmount: String(cash),
        phonePeAmount: String(phonepe),
        creditAmount: String(credit),
        paymentAmount: String(total),
        clinicId: String(user.id),
        clinicName: user.name,
        date: today,
        token: finalToken,
        visitCount: visitCount,
        createdAt: new Date(),
        status: opdForm.status || "waiting",
      };

      if (opdIdToUpdate) {
        await firebaseService.updateDocument("opd_queue", opdIdToUpdate, opdData);
      } else {
        await firebaseService.addDocument("opd_queue", opdData);
      }

      // Also mark associated appointment as confirmed if set!
      if (associatedAppointmentId) {
        await firebaseService.updateDocument("appointments", associatedAppointmentId, {
          status: "confirmed",
        });
      }

      // Record in payment history if any payment made
      if (cash > 0) {
        await firebaseService.addDocument("credit_payment_history", {
          clinicId: String(user.id),
          patientName: opdForm.patientName,
          patientPhone: opdForm.patientPhone,
          paidAmount: cash,
          paymentMode: "cash",
          type: "OPD",
          createdAt: new Date(),
        });
      }
      if (phonepe > 0) {
        await firebaseService.addDocument("credit_payment_history", {
          clinicId: String(user.id),
          patientName: opdForm.patientName,
          patientPhone: opdForm.patientPhone,
          paidAmount: phonepe,
          paymentMode: "phonepe",
          type: "OPD",
          createdAt: new Date(),
        });
      }
      if (credit > 0) {
        await firebaseService.addDocument("credit_records", {
          clinicId: String(user.id),
          patientName: opdForm.patientName,
          patientPhone: opdForm.patientPhone,
          totalAmount: total,
          paidAmount: cash + phonepe,
          balance: credit,
          paymentMode: "credit",
          status: "pending",
          createdAt: new Date(),
        });
      }

      // Refresh history if viewing today's history
      if (showOpdHistory && opdHistoryDate === today) {
        fetchOPDHistory(today);
      }

      setShowAddOPDModal(false);
      setOpdIdToUpdate(null);
      setAssociatedAppointmentId(null);
      setOpdForm({
        patientName: "",
        patientAge: "",
        patientPhone: "",
        patientGender: "M",
        weight: "",
        bp: "",
        sugar: "",
        temp: "",
        complaint: "",
        patientArea: "",
        diagnosis: "",
        cashAmount: "",
        phonePeAmount: "",
        creditAmount: "",
        status: "waiting",
        token: 0,
        priorityClass: "Regular",
        visitOption: "1st Visit",
      });
      setPatientSearchQuery("");

      // Optional: Send WhatsApp to patient about their token
      if (sendTokenEnabled && opdForm.patientPhone && isTokenSystemEnabled) {
        const currentActiveToken = opdQueue.find((p) => p.status === "consulting")?.token || "सुरू व्हायचा आहे";
        const msg = `🏥 *Carebridge+ Professional Smart OPD Queue* 🏥\n\nDear *${opdForm.patientName}*,\n\nYour professional OPD registration has been completed successfully at *${user.name}*.\n\n⏱️ *Smart OPD Queue Insights:*\n• *Clinic Partner:* ${user.name}\n• *Assigned Token Number:* #${finalToken}\n• *Active Live Token:* #${currentActiveToken}\n• *Facility Location:* ${clinicDetails?.address || "our facility"}\n\nTo ensure comfortable and seamless consulting, please arrive 10 minutes prior to your turn.\n\nSincerely,\n*Clinical Operations Desk*`;

        openWhatsAppPreview(opdForm.patientPhone, msg, "OPD Token Priority", opdForm.patientName, "token", {
          clinicName: user.name,
          clinicAddress: clinicDetails?.address || "our facility",
          token: finalToken,
          currentToken: currentActiveToken
        });
      }

      setConfirmModal({
        isOpen: true,
        title: "Success",
        message: "Patient added/updated in OPD queue successfully!",
        type: "info",
        onConfirm: () => { },
      });
    } catch (err) {
      console.error("Error adding to OPD queue:", err);
      setConfirmModal({
        isOpen: true,
        title: "Error",
        message: "Failed to process patient in queue. Please try again.",
        type: "danger",
        onConfirm: () => { },
      });
    } finally {
      setIsOpdSubmitting(false);
    }
  };

