  const handleApproveAsRegistration = async (apt: any) => {
    try {
      // 1. Update appointment status to confirmed
      await firebaseService.updateDocument("appointments", apt.id, {
        status: "confirmed",
      });

      // 2. Pre-fill the offline OPD registration form
      setOpdForm({
        patientName: apt.patientName || "",
        patientAge: apt.patientAge || "",
        patientPhone: apt.patientPhone || "",
        patientGender: apt.patientGender || "M",
        weight: apt.weight || "",
        bp: apt.bp || "",
        sugar: apt.sugar || "",
        temp: apt.temp || "",
        complaint: apt.complaint || "Online Booking Consultation",
        patientArea: apt.patientAddress || apt.patientArea || "",
        diagnosis: "",
        cashAmount: "",
        phonePeAmount: "",
        creditAmount: "",
        status: "registration", // Stays in registration queue until offline registration form is filled & submitted with fees!
        token: 0,
        priorityClass: "Regular",
        visitOption: "1st Visit",
      });

      // Track that we are processing this appointment
      setAssociatedAppointmentId(apt.id);

      // Create a queue entry in "registration" status
      const existingReq = opdQueue.find(
        (p) => p.appointmentId === apt.id && p.status === "requested",
      );

      if (existingReq) {
        await firebaseService.updateDocument("opd_queue", existingReq.id, {
          status: "registration",
          updatedAt: serverTimestamp(),
        });
        setOpdIdToUpdate(existingReq.id);
      } else {
        const addedDoc = await firebaseService.addDocument("opd_queue", {
          clinicId: String(user.id),
          clinicName: user.name,
          patientName: apt.patientName,
          patientAge: apt.patientAge || "",
          patientPhone: apt.patientPhone,
          patientGender: apt.patientGender || "M",
          patientArea: apt.patientAddress || apt.patientArea || "",
          status: "registration",
          token: 0,
          date: apt.appointmentDate || getISTDateString(),
          createdAt: serverTimestamp(),
          type: "online",
          appointmentId: apt.id,
        });
        if (addedDoc && addedDoc.id) {
          setOpdIdToUpdate(addedDoc.id);
        }
      }

      setApprovalModal({ isOpen: false, appointment: null });
      setShowAddOPDModal(true);

      setConfirmModal({
        isOpen: true,
        title: "Registration Form Started",
        message: `Offline registration form opened with properties pre-populated for ${apt.patientName}. Complete the registration fees entry to log payments.`,
        type: "info",
        onConfirm: () => setConfirmModal((prev) => ({ ...prev, isOpen: false })),
      });
    } catch (err) {
      console.error("Error setting up registration queue:", err);
    }
  };

