                    {/* CLINICAL PHYSIOLOGICAL VITAL ALERTS */}
                    {(() => {
                      const alerts: string[] = [];
                      const vitals: any = prescriptionForm.vitals || {};
                      if (vitals.bp) {
                        const parts = vitals.bp.split("/");
                        const sys = parseInt(parts[0]) || 0;
                        const dia = parseInt(parts[1]) || 0;
                        if (sys >= 160 || dia >= 100) {
                          alerts.push("⚠️ CRITICAL hypertensives alert (>160/100)");
                        } else if (sys >= 140 || dia >= 90) {
                          alerts.push("⚠️ BP Stage-2 Hypertension Warning");
                        } else if (sys && sys < 90) {
                          alerts.push("⚠️ Low BP warning (Hypotension)");
                        }
                      }
                      if (vitals.temp) {
                        const t = parseFloat(vitals.temp) || 0;
                        if (t >= 102) {
                          alerts.push("🌡️ High Pyrexia Fever (>102°F)");
                        } else if (t > 99.4) {
                          alerts.push("🌡️ Low-grade fever hyperthermia");
                        }
                      }
                      if (vitals.pulse) {
                        const p = parseInt(vitals.pulse) || 0;
                        if (p >= 100) {
                          alerts.push("💓 High HR Tachycardia warning");
                        } else if (p > 0 && p < 60) {
                          alerts.push("💓 Low HR Bradycardia warning");
                        }
                      }
                      if (vitals.spo2) {
                        const s = parseInt(vitals.spo2) || 0;
                        if (s > 0 && s < 94) {
                          alerts.push("🚨 Hypoxia Alert: Critical SpO2 < 94%");
                        }
                      }
                      if (vitals.sugar) {
                        const sug = parseInt(vitals.sugar) || 0;
                        if (sug >= 200) {
                          alerts.push("🚨 Hyperglycemia sugar warning");
                        } else if (sug > 0 && sug < 70) {
                          alerts.push("🚨 Severe Hypoglycemia Risk");
                        }
                      }

                      if (alerts.length === 0) return null;

                      return (
                        <div className="bg-red-500/10 border border-red-500/15 p-2 rounded-2xl flex flex-col gap-1 sm:flex-row sm:items-center sm:gap-2.5">
                          <span className="text-[9px] font-black text-red-500 uppercase tracking-wider flex items-center gap-1.5 shrink-0">
                            <AlertCircle size={12} className="animate-bounce" /> Clinical Alerts:
                          </span>
                          <div className="flex flex-wrap gap-1">
                            {alerts.map((al, ai) => (
                              <span key={ai} className="bg-red-600 font-extrabold text-white text-[8px] px-2 py-0.5 rounded-md uppercase">
                                {al}
                              </span>
                            ))}
                          </div>
                        </div>
                      );
                    })()}

